ng{font-size:40px;line-height:1.3}.track{height:10px;border-radius:99px;background:#0d191e;margin:10px 0 20px;overflow:hidden}.fill{height:100%;background:var(--amber)}.after .fill{background:var(--mint)}.detail{display:flex;gap:24px;border-top:1px solid var(--line);padding-top:16px;font-size:13px}.detail strong{font-size:22px;margin-left:6px}.note{border-left:3px solid var(--line);padding-left:18px;color:var(--muted);font-size:13px;margin:20px 0}.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:12px}table{border-collapse:collapse;width:100%;white-space:nowrap}th,td{text-align:left;padding:12px 18px;border-bottom:1px solid var(--line)}th{background:var(--panel);font-size:12px;color:var(--muted)}td{font-size:13px}tr:last-child td{border-bottom:0}tbody tr:hover{background:#1c3037}.bar-value{display:flex;align-items:center;gap:12px}.mini{height:6px;background:var(--mint);display:inline-block;border-radius:4px;min-width:0}.pill{background:#294334;color:var(--mint);border-radius:4px;padding:3px 8px;font-size:11px}.pill.fail{background:#523834;color:var(--red)}code{font:13px/1.6 ui-monospace,monospace;color:#d6e9d3}.foot{margin-top:40px;border-top:1px solid var(--line);padding-top:20px;color:var(--muted);font-size:12px}.links{display:flex;flex-wrap:wrap;gap:18px;margin-top:16px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.steps p{font-size:13px;color:var(--muted);margin-bottom:0}@media(max-width:750px){main{padding:24px 16px}.stats{grid-template-columns:repeat(2,1fr)}.compare,.steps{grid-template-columns:1fr}.hero{display:block}.board{display:none}.section-head{display:block}.number{font-size:30px}header{align-items:flex-start}.tag{white-space:nowrap}th,td{padding:10px 12px}}
